private void ExportToanKhoaHTML()
{
    if (dtbData == null || dtbClassSubject == null || dtbData.Rows.Count <= 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    bool bolIsTinChi = (intRegulationIDCurrent == 99 || intRegulationIDCurrent == 43 || intRegulationIDCurrent == 44);
    int intMaxSubject = 44;
    int intSubjectCount = dtbClassSubject.Rows.Count;
    if (intSubjectCount > intMaxSubject)
        intSubjectCount = intMaxSubject;

    string strTemplateFile = "MauHtml\\BangDiemToanKhoa_QC99.htm";
    string strFileContent = "";
    try
    {
        strFileContent = Libs.Files.ReadFile(strTemplateFile);
    }
    catch
    {
        string strFullPath = Application.StartupPath + "\\" + strTemplateFile;
        if (System.IO.File.Exists(strFullPath))
            strFileContent = System.IO.File.ReadAllText(strFullPath, Encoding.UTF8);
    }

    if (strFileContent == null || strFileContent.Length == 0)
    {
        ErrorManager.Error("Không tìm thấy file mẫu HTML: " + strTemplateFile);
        return;
    }

    GetSetting();
    string strBranchLabel = "Chuyên ngành";
    if (uClass.RegulationID == 25)
        strBranchLabel = "Ngành";

    strFileContent = strFileContent.Replace("{REPORT_HEADER_TEXT}", SystemService.SYS_SettingService.GetStringValue("Report_Header_Text"));
    strFileContent = strFileContent.Replace("{REPORT_HEADER2_TEXT}", SystemService.SYS_SettingService.GetStringValue("Report_Header2_Text"));
    strFileContent = strFileContent.Replace("{COURSE}", uClass.CourseName);
    strFileContent = strFileContent.Replace("{TRAINING_LEVEL}", uClass.TrainingLevelName);
    strFileContent = strFileContent.Replace("{SPECIAL_BRANCH}", uClass.SpecialBranchName);
    strFileContent = strFileContent.Replace("{CLASS}", uClass.ClassName);
    strFileContent = strFileContent.Replace("{BRANCH_LABEL}", strBranchLabel);
    strFileContent = strFileContent.Replace("{REPORT_PLACE}", strReport_Place);
    strFileContent = strFileContent.Replace("{TOTAL_STUDENT}", dtbData.Rows.Count.ToString());
    strFileContent = strFileContent.Replace("{TABLE_CONTENT}", BuildToanKhoaTableHTML(intSubjectCount, bolIsTinChi));
    strFileContent = strFileContent.Replace("{STATISTIC}", BuildToanKhoaStatisticHTML());

    string strFileNameAs = Application.StartupPath + "\\Export\\BangDiemToanKhoa_" + uClass.ClassIDEditValue.ToString() + ".htm";
    string strExportDir = Application.StartupPath + "\\Export";
    if (!System.IO.Directory.Exists(strExportDir))
        System.IO.Directory.CreateDirectory(strExportDir);

    System.IO.File.WriteAllText(strFileNameAs, strFileContent, Encoding.UTF8);
    System.Diagnostics.Process.Start(strFileNameAs);
}

private string BuildToanKhoaTableHTML(int intSubjectCount, bool bolIsTinChi)
{
    StringBuilder sb = new StringBuilder();
    sb.Append("<table class=\"data-table\">\r\n");

    // Dòng tên môn học (xoay dọc)
    sb.Append("<tr>\r\n");
    sb.Append("<th rowspan=\"2\" class=\"col-tt\">TT</th>\r\n");
    sb.Append("<th rowspan=\"2\" class=\"col-code\">Mã số</th>\r\n");
    sb.Append("<th rowspan=\"2\" class=\"col-name\">Họ và tên</th>\r\n");
    for (int i = 0; i < intSubjectCount; i++)
    {
        DataRow drwSubject = dtbClassSubject.Rows[i];
        sb.Append("<th><div class=\"vertical-header\">");
        sb.Append(System.Web.HttpUtility.HtmlEncode(drwSubject["SubjectName"].ToString()));
        sb.Append("</div></th>\r\n");
    }
    sb.Append("<th rowspan=\"2\" class=\"col-summary\">TBC<br/>tích<br/>lũy<br/>(T04)</th>\r\n");
    sb.Append("<th rowspan=\"2\" class=\"col-summary\">TBC<br/>tích<br/>lũy<br/>(T10)</th>\r\n");
    sb.Append("<th rowspan=\"2\" class=\"col-summary\">Số TC<br/>tích<br/>lũy</th>\r\n");
    sb.Append("<th rowspan=\"2\" class=\"col-summary\">Số HP<br/>Thi<br/>lại</th>\r\n");
    sb.Append("</tr>\r\n");

    // Dòng số tín chỉ
    sb.Append("<tr>\r\n");
    for (int i = 0; i < intSubjectCount; i++)
    {
        DataRow drwSubject = dtbClassSubject.Rows[i];
        sb.Append("<th class=\"unit-header\">");
        sb.Append(drwSubject["UnitText"].ToString());
        sb.Append("</th>\r\n");
    }
    sb.Append("</tr>\r\n");

    // Dòng dữ liệu sinh viên
    int intTT = 0;
    foreach (DataRow drw in dtbData.Rows)
    {
        intTT++;
        sb.Append("<tr>\r\n");
        sb.Append("<td>").Append(intTT.ToString()).Append("</td>\r\n");
        sb.Append("<td>").Append(System.Web.HttpUtility.HtmlEncode(drw["StudentCode"].ToString())).Append("</td>\r\n");
        sb.Append("<td class=\"col-name\">");
        sb.Append(System.Web.HttpUtility.HtmlEncode(drw["StudentFirstName"].ToString()));
        sb.Append(" ");
        sb.Append(System.Web.HttpUtility.HtmlEncode(drw["StudentLastName"].ToString()));
        sb.Append("</td>\r\n");

        for (int i = 1; i <= intSubjectCount; i++)
        {
            string strColName = bolIsTinChi ? ("OtherFinalSummary_" + i.ToString()) : ("FinalSummary_" + i.ToString());
            sb.Append("<td class=\"col-mark\">");
            sb.Append(FormatMarkValue(drw, strColName, bolIsTinChi ? 1 : 1));
            sb.Append("</td>\r\n");
        }

        sb.Append("<td>").Append(FormatMarkValue(drw, "OtherSummaryLearningMark", 2)).Append("</td>\r\n");
        sb.Append("<td>").Append(FormatMarkValue(drw, "SummaryLearningMark", 1)).Append("</td>\r\n");
        sb.Append("<td>").Append(FormatIntegerValue(drw, "PassedUnitTextSum_All")).Append("</td>\r\n");
        sb.Append("<td>").Append(FormatIntegerValue(drw, "SoMonBinhThuongThiLai")).Append("</td>\r\n");
        sb.Append("</tr>\r\n");
    }

    sb.Append("</table>\r\n");
    return sb.ToString();
}

private string BuildToanKhoaStatisticHTML()
{
    int iTB = 0;
    int iTBKha = 0;
    int iKha = 0;
    int iTot = 0;
    int iXuatSac = 0;
    int iSV = dtbData.Rows.Count;
    int iYeu = 0;

    for (int j = 0; j < dtbData.Rows.Count; j++)
    {
        string strLevel = Convert.ToString(dtbData.Rows[j]["LearningLevel"]);
        if (strLevel == "Yếu" || strLevel == "Kém")
            iYeu += 1;
        else if (strLevel == "Trung bình")
            iTB += 1;
        else if (strLevel == "TB khá")
            iTBKha += 1;
        else if (strLevel == "Khá")
            iKha += 1;
        else if (strLevel == "Giỏi")
            iTot += 1;
        else if (strLevel == "Xuất sắc")
            iXuatSac += 1;
    }

    StringBuilder sb = new StringBuilder();
    sb.Append("<table class=\"stat-table\">\r\n");
    sb.Append("<tr><th>Xếp loại</th><th>SL</th><th>Tỉ lệ</th><th>Xếp loại</th><th>SL</th><th>Tỉ lệ</th></tr>\r\n");

    AppendStatisticRow(sb, "Xuất sắc", iXuatSac, iSV, "Giỏi", iTot, iSV);
    AppendStatisticRow(sb, "Khá", iKha, iSV, "TB khá", iTBKha, iSV);
    AppendStatisticRow(sb, "Trung bình", iTB, iSV, "Yếu - Kém", iYeu, iSV);

    sb.Append("</table>\r\n");
    return sb.ToString();
}

private void AppendStatisticRow(StringBuilder sb, string strLabel1, int intCount1, int intTotal, string strLabel2, int intCount2, int intTotalAll)
{
    sb.Append("<tr>");
    sb.Append("<td>").Append(strLabel1).Append("</td>");
    sb.Append("<td>").Append(intCount1.ToString()).Append("</td>");
    sb.Append("<td>").Append(CalcPercent(intCount1, intTotalAll)).Append("</td>");
    sb.Append("<td>").Append(strLabel2).Append("</td>");
    sb.Append("<td>").Append(intCount2.ToString()).Append("</td>");
    sb.Append("<td>").Append(CalcPercent(intCount2, intTotalAll)).Append("</td>");
    sb.Append("</tr>\r\n");
}

private string CalcPercent(int intCount, int intTotal)
{
    if (intTotal <= 0)
        return "0%";
    return Math.Round((double)intCount * 100 / intTotal, 0).ToString() + "%";
}

private string FormatMarkValue(DataRow drw, string strColumn, int intDecimals)
{
    if (!dtbData.Columns.Contains(strColumn))
        return "&nbsp;";

    object objValue = drw[strColumn];
    if (objValue == null || objValue == DBNull.Value || objValue.ToString() == "")
        return "&nbsp;";

    if (objValue.ToString() == "-1")
        return "M";

    double dblValue = Convert.ToDouble(objValue);
    if (intDecimals == 2)
        return dblValue.ToString("0.00");
    return dblValue.ToString("0.0");
}

private string FormatIntegerValue(DataRow drw, string strColumn)
{
    if (!dtbData.Columns.Contains(strColumn))
        return "&nbsp;";

    object objValue = drw[strColumn];
    if (objValue == null || objValue == DBNull.Value || objValue.ToString() == "")
        return "&nbsp;";

    return Convert.ToInt32(Convert.ToDouble(objValue)).ToString();
}

